    for i in range(m):
        for d in range(4):
            value = DUALS[sigma[i]][d]
            mat[i, m + d] = value
            mat[m + d, i] = value
        mat[i, m + 4] = 1
        mat[m + 4, i] = 1
    rhs[m + 4] = 1
    return mat, rhs

def q_value(sigma, beta):
    q = 0
    for i in range(1, len(sigma)):
        for j in range(i):
            q += (beta[i] * beta[j]
                  * omega(DUALS[sigma[j]], DUALS[sigma[i]]))
    return reduced(q)

